// Render candlestick shape with proper wick positioning
const renderCandlestick = (props) => {
  const { x, width, payload, height: barHeight, y: barY } = props;
  if (!payload) return null;

  const candleWidth = Math.min(width * 0.6, 20);
  const wickWidth = 2;
  const candleX = x + width / 2 - candleWidth / 2;
  const wickX = x + width / 2 - wickWidth / 2;

  // Calculate the full chart range for accurate positioning
  const [yMin, yMax] = yDomain;
  const chartRange = yMax - yMin;
  const chartHeight = 400 - 40; // Total height minus top/bottom margins

  // Convert price values to pixel positions (top to bottom)
  const priceToY = (price) => {
    return ((yMax - price) / chartRange) * chartHeight + 20; // +20 for top margin
  };

  const highY = priceToY(payload.high);
  const lowY = priceToY(payload.low);
  const bodyTopY = priceToY(payload.bodyTop);
  const bodyBottomY = priceToY(payload.bodyBottom);

  // Calculate heights
  const upperWickHeight = bodyTopY - highY;
  const lowerWickHeight = lowY - bodyBottomY;
  const bodyHeight = Math.max(bodyBottomY - bodyTopY, 1); // Minimum 1px for doji

  return (
    <g>
      {/* Upper wick */}
      {upperWickHeight > 0 && (
        <rect
          x={wickX}
          y={highY}
          width={wickWidth}
          height={upperWickHeight}
          fill={payload.fill}
        />
      )}
      {/* Candle body */}
      <rect
        x={candleX}
        y={bodyTopY}
        width={candleWidth}
        height={bodyHeight}
        fill={payload.fill}
        stroke={payload.fill}
        strokeWidth={1}
      />
      {/* Lower wick */}
      {lowerWickHeight > 0 && (
        <rect
          x={wickX}
          y={bodyBottomY}
          width={wickWidth}
          height={lowerWickHeight}
          fill={payload.fill}
        />
      )}
    </g>
  );
};

