/**
 * Express app module — separated from server.js for testability.
 * server.js imports this and calls listen().
 * Tests import this directly with supertest.
 */
const express = require('express');
const cors = require('cors');
const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');

function createApp(options = {}) {
  const app = express();
  const WATCHLIST_FILE = options.watchlistFile ||
    path.join(__dirname, '..', process.env.WATCHLIST_FILE_PATH || 'watchlist.json');

  // Middleware
  app.use(cors({ origin: process.env.CORS_ORIGIN || 'http://localhost:3000' }));
  app.use(express.json());

  // Request logging (suppress in test)
  if (process.env.NODE_ENV !== 'test') {
    app.use((req, res, next) => {
      console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
      next();
    });
  }

  // ── Rate limit tracking for NewsAPI ────────────────────────────────
  let newsRequestCount = 0;
  let newsResetTime = null;

  function resetNewsRateLimit() {
    const now = new Date();
    const nextMidnight = new Date(
      Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1, 0, 0, 0, 0)
    );

    if (!newsResetTime || now >= new Date(newsResetTime)) {
      newsRequestCount = 0;
      newsResetTime = nextMidnight.toISOString();
    }
  }

  // Expose rate-limit internals for testing
  app._getNewsRateLimit = () => ({ newsRequestCount, newsResetTime });
  app._setNewsRateLimit = (count, resetTime) => {
    newsRequestCount = count;
    newsResetTime = resetTime;
  };

  // ── Watchlist initializer ──────────────────────────────────────────
  app.initializeWatchlist = async function () {
    try {
      await fs.access(WATCHLIST_FILE);
    } catch {
      const defaultWatchlist = {
        assets: ['BTC', 'ETH', 'SOL'],
        lastUpdated: new Date().toISOString(),
      };
      await fs.writeFile(WATCHLIST_FILE, JSON.stringify(defaultWatchlist, null, 2));
    }
  };

  // ── Watchlist routes ───────────────────────────────────────────────
  app.get('/api/watchlist', async (req, res) => {
    try {
      const data = await fs.readFile(WATCHLIST_FILE, 'utf8');
      const watchlist = JSON.parse(data);
      res.json({ success: true, data: watchlist, error: null });
    } catch (error) {
      console.error('Error reading watchlist:', error);
      res.status(500).json({
        success: false,
        data: null,
        error: {
          code: 'watchlist_read_error',
          message: 'Failed to read watchlist',
          details: { error: error.message },
        },
      });
    }
  });

  app.post('/api/watchlist', async (req, res) => {
    try {
      const { asset } = req.body;

      // Validation
      if (!asset || typeof asset !== 'string') {
        return res.status(400).json({
          success: false,
          data: null,
          error: {
            code: 'validation_error',
            message: 'Asset symbol is required',
            details: { field: 'asset' },
          },
        });
      }

      const symbol = asset.toUpperCase().trim();
      if (!/^[A-Z]{2,10}$/.test(symbol)) {
        return res.status(400).json({
          success: false,
          data: null,
          error: {
            code: 'validation_error',
            message: 'Asset symbol must be 2-10 uppercase letters',
            details: { field: 'asset', value: asset },
          },
        });
      }

      // Read current watchlist
      const data = await fs.readFile(WATCHLIST_FILE, 'utf8');
      const watchlist = JSON.parse(data);

      // Check for duplicates
      if (watchlist.assets.includes(symbol)) {
        return res.status(400).json({
          success: false,
          data: null,
          error: {
            code: 'duplicate_asset',
            message: `${symbol} is already in your watchlist`,
            details: { asset: symbol },
          },
        });
      }

      // Check max limit
      if (watchlist.assets.length >= 50) {
        return res.status(400).json({
          success: false,
          data: null,
          error: {
            code: 'watchlist_limit_exceeded',
            message: 'Watchlist is full (max 50 assets)',
            details: { currentCount: watchlist.assets.length },
          },
        });
      }

      // Add asset
      watchlist.assets.push(symbol);
      watchlist.lastUpdated = new Date().toISOString();
      await fs.writeFile(WATCHLIST_FILE, JSON.stringify(watchlist, null, 2));

      res.json({ success: true, data: watchlist, error: null });
    } catch (error) {
      console.error('Error adding to watchlist:', error);
      res.status(500).json({
        success: false,
        data: null,
        error: {
          code: 'watchlist_write_error',
          message: 'Failed to add asset to watchlist',
          details: { error: error.message },
        },
      });
    }
  });

  app.delete('/api/watchlist/:asset', async (req, res) => {
