          error: {
            code: 'unsupported_asset',
            message: 'Asset symbol not supported',
            details: { asset: rawSymbol },
          },
        });
      }

      const baseUrl = process.env.COINGECKO_BASE_URL || 'https://api.coingecko.com/api/v3';
      const response = await axios.get(`${baseUrl}/coins/${coinId}/ohlc`, {
