/**
 * Test helpers — shared setup/teardown and mock factories.
 *
 * Each test file that needs a fresh app calls `buildTestApp()`, which:
 *  - creates a unique temp watchlist file
 *  - seeds it with configurable initial assets
 *  - returns { app, watchlistFile, cleanup }
 *
 * axios is mocked at the module level via jest.mock('axios') in each
 * test file so CoinGecko / NewsAPI are never called for real.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');

/**
 * Create a disposable Express app backed by a temp watchlist file.
 *
 * @param {object}   opts
 * @param {string[]} opts.initialAssets  — seed assets  (default ['BTC','ETH','SOL'])
 * @returns {{ app: Express.Application, watchlistFile: string, cleanup: () => void }}
 */
function buildTestApp(opts = {}) {
  const initialAssets = opts.initialAssets ?? ['BTC', 'ETH', 'SOL'];

  // Write temp watchlist
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'crypto-test-'));
  const watchlistFile = path.join(tmpDir, 'watchlist.json');
  fs.writeFileSync(
    watchlistFile,
    JSON.stringify({
      assets: initialAssets,
      lastUpdated: new Date().toISOString(),
    }, null, 2),
  );

  // Force test env
  process.env.NODE_ENV = 'test';
  process.env.COINGECKO_BASE_URL = 'https://mock-coingecko.test/api/v3';
  process.env.NEWS_API_BASE_URL = 'https://mock-newsapi.test/v2';
  process.env.NEWS_API_KEY = 'test-api-key';

  const { createApp } = require('../app');
  const app = createApp({ watchlistFile });

  function cleanup() {
    try { fs.unlinkSync(watchlistFile); } catch { /* ignore */ }
    try { fs.rmdirSync(tmpDir); } catch { /* ignore */ }
  }

  return { app, watchlistFile, cleanup };
}

