/**
 * Integration tests — Watchlist CRUD
 *
 * Covers:
 *  1. GET  /api/watchlist       — retrieve current list
 *  2. POST /api/watchlist       — add valid asset, duplicate, invalid format, 50-limit
 *  3. DELETE /api/watchlist/:a   — remove existing, remove non-existent, invalid format
 *  4. Concurrent POSTs          — two simultaneous adds (race-condition note per spec)
 */
const request = require('supertest');
const fs = require('fs');
const { buildTestApp } = require('./helpers');

describe('Watchlist API', () => {
  let app, watchlistFile, cleanup;

  beforeEach(() => {
    ({ app, watchlistFile, cleanup } = buildTestApp({ initialAssets: ['BTC', 'ETH', 'SOL'] }));
  });

  afterEach(() => {
    cleanup();
  });

  // ── GET /api/watchlist ───────────────────────────────────────────

  describe('GET /api/watchlist', () => {
    it('returns the current watchlist with correct shape', async () => {
      const res = await request(app).get('/api/watchlist');

      expect(res.status).toBe(200);
      expect(res.body.success).toBe(true);
      expect(res.body.error).toBeNull();
      expect(res.body.data).toBeDefined();
      expect(res.body.data.assets).toEqual(['BTC', 'ETH', 'SOL']);
      expect(res.body.data.lastUpdated).toBeDefined();
    });

    it('returns empty assets array when watchlist is empty', async () => {
      cleanup();
      ({ app, watchlistFile, cleanup } = buildTestApp({ initialAssets: [] }));

      const res = await request(app).get('/api/watchlist');

      expect(res.status).toBe(200);
      expect(res.body.data.assets).toEqual([]);
    });
  });

